const cfg = $input.first().json;
let base = String(cfg.siteBaseUrl || '');
while (base.endsWith('/')) base = base.slice(0, -1);
if (!base.startsWith('http://') && !base.startsWith('https://')) throw new Error('Config: siteBaseUrl must start with http:// or https://');
const brand = cfg.brand || {};
const slug = String(brand.slug || '');
const api = base + '/api/automation/social/v1';
const articles = $('RSS Feed Trigger').all();
return articles.map((it, i) => {
  const a = it.json;
  const link = String(a.link || '');
  const eventId = String(a.guid || a.link || 'article-' + (a.isoDate || a.title || i)).slice(0, 200);
  return {
    json: {
      brand: slug,
      event_id: eventId,
      title: String(a.title || '').slice(0, 120),
      url: api + '/generation-requests',
      runsUrl: api + '/runs',
      body: {
        workflow: 'article-to-drafts',
        event_id: eventId,
        brand: slug,
        input: {
          source: { type: 'article', url: link },
          research: cfg.research === true,
          kinds: ['social'],
          count: Number(brand.count) || 3,
          language: 'ro',
          templates: Array.isArray(brand.templates) && brand.templates.length > 0 ? brand.templates : ['dark', 'light', 'mint'],
          platforms: brand.platforms,
        },
      },
    },
  };
});

const sent = $('Build requests').all();
return $input.all().map((item, i) => {
  const req = sent[i].json;
  const r = item.json;
  const body = r.body && typeof r.body === 'object' ? r.body : {};
  let status = 'error';
  const details = { brand: req.brand, title: req.title };
  if (r.error !== undefined) {
    details.error = String(r.error.message || r.error).slice(0, 300);
  } else if (r.statusCode >= 200 && r.statusCode < 300) {
    status = body.created === false ? 'skipped' : 'ok';
    details.statusCode = r.statusCode;
    details.request_id = body.request_id;
    details.created = body.created;
  } else {
    details.statusCode = r.statusCode;
    details.response = JSON.stringify(r.body === undefined ? null : r.body).slice(0, 300);
  }
  return { json: { url: req.runsUrl, body: { workflow: 'article-to-drafts', event_id: req.event_id, status, details } } };
});
